// Content pack 3 — The Arctic Searches, from both oceans (authored 2026-10-17).
//
// Scope: the search for the Northwest Passage from Frobisher in 1576 to Amundsen in 1906 and
// Bernier's sovereignty voyages, approached from the Atlantic (Davis Strait, Hudson Strait,
// Lancaster Sound) and from the Pacific (Bering Strait, the Beaufort Sea), with the Franklin
// search of 1848-1859 as the decade that mapped the archipelago, and the Inuit who guided,
// fed, interpreted for and finally explained the fate of the expeditions. Same rules as the
// earlier packs: Indigenous names only where the attestation is well known, no quoted
// transcriptions, portraits only where a likeness made in the person's lifetime is confirmed.
import type { PackWaterway, PackExplorer, PackLink, PackLocation, PackFigure, PackTimelineEvent, PackHistoricalEvent, PackPronunciation, PackGuide } from "./new-france-to-the-gulf";
import type { PackExplorerWithPortrait, PackFigureWithPortrait } from "./pacific-and-russians";

const wiki = (slug: string) => `https://en.wikipedia.org/wiki/${slug}`;
const dcb = (slug: string) => `https://www.biographi.ca/en/bio/${slug}.html`;
const tce = (slug: string) => `https://www.thecanadianencyclopedia.ca/en/article/${slug}`;
const W = (title: string, slug: string, description: string): PackGuide => ({ title, authorSource: "Wikipedia", url: wiki(slug), description, gradeLevel: "7-9" });
const DCB = (title: string, slug: string, description: string): PackGuide => ({ title, authorSource: "Dictionary of Canadian Biography", url: dcb(slug), description, gradeLevel: "10-12" });
const TCE = (title: string, slug: string, description: string): PackGuide => ({ title, authorSource: "The Canadian Encyclopedia", url: tce(slug), description, gradeLevel: "7-9" });

export type { PackImage, PackGuide } from "./new-france-to-the-gulf";

